1	// WHEN A BLOCKED ITEM MAY RUN, and who releases it (tasks-dispatch DESIGN §9,
2	// decision §15.19). Two callers ask the same question at different moments: the
3	// scheduler run, hourly, over every open item; and whoever CLOSES an item, immediately,
4	// over the dependents that item was holding. The predicate lives here so those
5	// two can never answer it differently — the failure that shape produces is a
6	// chain link that waits an hour on one path and runs at once on the other, with
7	// nothing red to say which is right.
8	//
9	// The scheduler run stays the backstop, deliberately: a close performed by a HUMAN (or by
10	// a session that stopped early) runs none of this, and the hourly pass is what
11	// makes that harmless rather than a chain that never resumes.
12	
13	import { BLOCKED, READY, STATUS_BLOCKED, isStatus, parseWorkItemBody } from './work-item.mjs';
14	import { swapStatus } from './apply-status.mjs';
15	
16	// Is this item's wait over? `stateOf(n)` answers the state of a `Blocked-by`
17	// target that may not be a work item at all — an unknown number is never treated
18	// as closed, so an unreadable blocker DELAYS rather than releases (the
19	// convergence-not-prevention posture). An item in triage is nobody's to release.
20	export function isReleasable(item, { stateOf = () => null, nowMs = Date.now() } = {}) {
21	  if (item.state !== 'open' || !isStatus(item, STATUS_BLOCKED)) return false;
22	  const { notBefore, blockedBy } = parseWorkItemBody(item.body);
23	  const blockersDone = blockedBy.every((n) => stateOf(n) === 'closed');
24	  const timeReached = notBefore === null || nowMs >= new Date(notBefore).getTime();
25	  return blockersDone && timeReached;
26	}
27	
28	// Which open items were waiting on THIS one, and are now free. Scoped to items
29	// naming `closedIssue` among their blockers: a close is not a general readiness
30	// sweep, and treating it as one would have every close re-derive the whole scheduler run.
31	export function releasedBy(closedIssue, open = [], { stateOf = () => null, nowMs = Date.now() } = {}) {
32	  const dependsOnIt = (i) => parseWorkItemBody(i.body).blockedBy.includes(closedIssue);
33	  return open.filter((i) => dependsOnIt(i) && isReleasable(i, { stateOf, nowMs }));
34	}
35	
36	// The shell: read the queue, release what this close freed, and say so. Returns
37	// the numbers readied, so the caller can decide whether the chain needs a run —
38	// this function starts none itself, because the executor's own drain (§10)
39	// already re-reads the queue after every settle and covers exactly this.
